onClick:
{{
  Delete_BL.run()
    .then(() => {
      // 1. On ferme la modale
      closeModal('modal_delete_BL');

      // 2. On affiche un message de succès
      showAlert('Bon de livraison supprimé avec succès', 'success');

      // 3. On retourne sur la page précédente (grâce à l'historique qu'on a mis en place)
      navigateTo(appsmith.store.page_precedente || 'Bon de livraison');
    })
    .catch((err) => {
      showAlert('Erreur lors de la suppression', 'error');
      console.error(err);
    });
}}
